#include <vector>
#include <algorithm>
#include <stdexcept>

int main() {
    std::vector<int> v1 = {1, 2, 3};
    std::vector<int> v2 = {4, 5, 6};

    // swap() is guaranteed not to throw, making it safe for cleanup.
    try {
        v1.swap(v2);
    } catch (...) {
        // This catch block will likely never be entered due to the guarantee.
    }

    // pop_back() is guaranteed not to throw (assuming int destructor doesn't throw)
    v1.pop_back(); 

    // clear() is guaranteed not to throw for POD types like int.
    v2.clear(); 
}
